def transform(grid):
    g = np.array(grid).copy()
    bg = background(g)
    H, W = g.shape
    objs = objects(g, bg=bg)
    o = max(objs, key=lambda d: d["size"])
    y0, x0, y1, x1 = o["box"]
    FILL = 8
    # 1. fill interior of the frame
    for y in range(y0 + 1, y1):
        for x in range(x0 + 1, x1):
            if g[y, x] == bg:
                g[y, x] = FILL
    emit(g, "Fill the inside of the frame with 8.")
    # 2. find the gap on the frame border and pour out of it
    gap = None
    for y in range(y0, y1 + 1):
        for x in range(x0, x1 + 1):
            if (y in (y0, y1) or x in (x0, x1)) and g[y, x] == bg:
                gap = (y, x)
    if gap is not None:
        gy, gx = gap
        if gy == y0:
            d = (-1, 0)
        elif gy == y1:
            d = (1, 0)
        elif gx == x0:
            d = (0, -1)
        else:
            d = (0, 1)
        y, x = gy, gx
        while 0 <= y < H and 0 <= x < W:
            if g[y, x] == bg:
                g[y, x] = FILL
            y += d[0]
            x += d[1]
        emit(g, "Fill the gap and draw a ray of 8 outward from it to the grid edge.")
    return g
